record.field:
if not record or (records and len(records) != 1):
    raise UserError(env._("Open one appointment to prepare its quotation."))

record.check_access("read")
if record._check_private_event_conditions():
    raise UserError(env._("Ask the calendar owner for access to the appointment details."))

orders = record.x_dental_sale_order_ids
if not orders:
    if not (record.active and record.user_can_edit and (record.appointment_type_id or record.opportunity_id)):
        raise UserError(env._("Open an active patient appointment or CRM meeting you can edit."))

    record.check_access("write")
    record.lock_for_update(allow_referencing=True)
    # A linked order can be outside this salesperson's record rules or active companies.
    if env["sale.order"].sudo().search_count([("x_dental_appointment_id", "=", record.id)], limit=1):
        raise UserError(env._("A quotation already exists for this appointment. Ask its owner for access."))

    opportunity = record.opportunity_id
    customer = opportunity.partner_id
    booker = record.appointment_booker_id
    if customer and booker and customer != booker and customer not in record.partner_ids:
        raise UserError(env._("The booking and opportunity have different contacts. Add the correct patient to the appointment before quoting."))

    patient = customer or booker
    if not patient:
        attendees = (record.partner_ids - record.partner_id).filtered("partner_share")
        if len(attendees) == 1:
            patient = attendees
    if not patient or not patient.active:
        raise UserError(env._("Select an active patient on the opportunity or appointment before quoting."))

    company = opportunity.company_id or record.user_id.company_id or env.company
    quotation_context = {key: value for key, value in env.context.items() if not key.startswith("default_")}
    if opportunity:
        quotation_context.update(opportunity._prepare_opportunity_quotation_context())
    appointment = record.with_context(quotation_context).with_company(company)
    appointment.write({"x_dental_sale_order_ids": [Command.create({
        "partner_id": patient.id,
        "company_id": company.id,
        "opportunity_id": opportunity.id,
    })]})
    orders = appointment.x_dental_sale_order_ids

action = {
    "type": "ir.actions.act_window",
    "name": env._("Quotations / Orders"),
    "res_model": "sale.order",
    "views": [(False, "list"), (False, "form")],
    "domain": [("x_dental_appointment_id", "=", record.id)],
    "context": {"create": False, "allowed_company_ids": orders.env.companies.ids},
}
if len(orders) == 1:
    action.update(res_id=orders.id, views=[(False, "form")])

if record:
    record.check_access("read")
    appointment = record.x_dental_appointment_id
    if appointment:
        appointment.check_access("read")
        action = {
            "type": "ir.actions.act_window",
            "name": env._("Appointment"),
            "res_model": "calendar.event",
            "views": [(False, "form")],
            "res_id": appointment.id,
        }
